async function cssnanoMinify(input, sourceMap, minimizerOptions = {
  preset: "default"
}) {
  




  const load = async mod => {
    let exports;
    try {
      exports = require(mod);
      return exports;
    } catch (err) {
      let importESM;
      try {
        
        importESM = new Function("id", "return import(id);");
      } catch (_err) {
        importESM = null;
      }
      if (
      err.code === "ERR_REQUIRE_ESM" && importESM) {
        exports = await importESM(mod);
        return exports.default;
      }
      throw err;
    }
  };
  let postcss;
  let cssnano;
  try {
    postcss = require("postcss");
    cssnano = require("cssnano");
  } catch (err) {
    return {
      errors: [(err)]
    };
  }
  const [[name, code]] = Object.entries(input);
  
  const postcssOptions = {
    from: name,
    ... minimizerOptions.processorOptions
  };
  if (typeof postcssOptions.parser === "string") {
    try {
      postcssOptions.parser = await load(postcssOptions.parser);
    } catch (error) {
      throw new Error(`Loading PostCSS "${postcssOptions.parser}" parser failed: ${ error.message}\n\n(@${name})`, {
        cause: error
      });
    }
  }
  if (typeof postcssOptions.stringifier === "string") {
    try {
      postcssOptions.stringifier = await load(postcssOptions.stringifier);
    } catch (error) {
      throw new Error(`Loading PostCSS "${postcssOptions.stringifier}" stringifier failed: ${ error.message}\n\n(@${name})`, {
        cause: error
      });
    }
  }
  if (typeof postcssOptions.syntax === "string") {
    try {
      postcssOptions.syntax = await load(postcssOptions.syntax);
    } catch (error) {
      throw new Error(`Loading PostCSS "${postcssOptions.syntax}" syntax failed: ${ error.message}\n\n(@${name})`, {
        cause: error
      });
    }
  }
  if (sourceMap) {
    postcssOptions.map = {
      annotation: false
    };
  }
  const result = await postcss.default([cssnano(minimizerOptions)]).process(code, postcssOptions);
  return {
    code: result.css,
    map: result.map ? (
    result.map.toJSON()) : undefined,
    warnings: result.warnings().map(String)
  };
}




cssnanoMinify.getMinimizerVersion = () => {
  let packageJson;
  try {
    packageJson = require("cssnano/package.json");
  } catch (_err) {
    
  }
  return packageJson && packageJson.version;
};




